INSERT INTO seed_cases VALUES
 ('N001', 'TP2000000001', 'TP3000000002', 3300, '2026-09-02 10:07+05:30', 'A man said he was from a courier company and my parcel was stuck at customs. He asked me to pay a clearance fee by UPI.'),
 ('N002', 'TP2000000002', 'TP3000000003', 4700, '2026-09-03 11:14+05:30', 'Got a call that a package in my name was held at the airport and I had to pay customs duty immediately or face a police case.'),
 ('N003', 'TP2000000003', 'TP3000000004', 6100, '2026-09-04 12:21+05:30', 'Someone posing as a delivery agent said my shipment needed a small re-delivery charge, sent a payment link and took my money.'),
 ('N004', 'TP2000000004', 'TP3000000005', 7400, '2026-09-05 13:28+05:30', 'Received SMS about failed parcel delivery with a link. I paid the address update fee and then more money was taken.'),
 ('N005', 'TP2000000005', 'TP3000000006', 8800, '2026-09-06 14:35+05:30', 'Caller claimed to be from DHL and said a box with illegal items was booked using my Aadhaar. They demanded a fee to clear my name.'),
 ('N006', 'TP2000000006', 'TP3000000007', 10200, '2026-09-07 15:42+05:30', 'Courier executive told me my international gift parcel had customs tax pending and I transferred the amount to his account.'),
 ('N007', 'TP2000000007', 'TP3000000008', 11600, '2026-09-08 16:49+05:30', 'They said my courier contained drugs and a customs officer would arrest me unless I paid a verification charge immediately.'),
 ('N008', 'TP2000000008', 'TP3000000009', 12900, '2026-09-09 17:56+05:30', 'Parcel from abroad supposedly needed an import fee. The person on WhatsApp sent a QR code and I paid twice.'),
 ('N009', 'TP2000000009', 'TP3000000010', 14300, '2026-09-10 18:03+05:30', 'Fake logistics company message said delivery was on hold for a pending shipping charge; after paying, the number was switched off.'),
 ('N010', 'TP2000000010', 'TP3000000001', 15700, '2026-09-11 09:10+05:30', 'I was told a package addressed to me was seized at customs and I must pay a penalty online to release it.'),
 ('N011', 'TP2000000011', 'TP3000000002', 17100, '2026-09-12 10:17+05:30', 'Message said my bank KYC had expired and the account would be blocked today. I clicked the link and entered my OTP.'),
 ('N012', 'TP2000000012', 'TP3000000003', 18400, '2026-09-13 11:24+05:30', 'Caller pretending to be from the bank asked me to update my PAN details to avoid account suspension and took my OTP.'),
 ('N013', 'TP2000000013', 'TP3000000004', 19800, '2026-09-14 12:31+05:30', 'Got an SMS that my SIM KYC was incomplete. The executive made me install a screen sharing app and money left my account.'),
 ('N014', 'TP2000000014', 'TP3000000005', 21200, '2026-09-15 13:38+05:30', 'Someone said my net banking would be frozen unless I re-verified KYC through their link. After that unauthorised debits happened.'),
 ('N015', 'TP2000000015', 'TP3000000006', 22500, '2026-09-16 14:45+05:30', 'A person from customer care told me my debit card KYC was pending and asked for card number, expiry and the OTP.'),
 ('N016', 'TP2000000016', 'TP3000000007', 23900, '2026-09-17 15:52+05:30', 'Received a call about updating Aadhaar linking with my account. They sent a form link and emptied my savings.'),
 ('N017', 'TP2000000017', 'TP3000000008', 25300, '2026-09-18 16:59+05:30', 'Bank officer on phone said my account would be closed for incomplete KYC, made me share the code that came by SMS.'),
